UPDATE marketing_task_export_job SET status='SUCCESS',storage_key=#{storageKey},
  file_name=#{fileName},content_type='text/csv;charset=UTF-8',file_size=#{fileSize},
  detail_row_count=#{rowCount},lease_until=NULL,claim_token=NULL,error_message=NULL,
  finished_at=#{finishedAt},expires_at=#{expiresAt},updated_at=#{finishedAt}
WHERE tenant_id=#{tenantId} AND id=#{id} AND status='PROCESSING' AND claim_token=#{claimToken}

UPDATE marketing_task_export_job SET status='FAILED',error_message=#{errorMessage},
  lease_until=NULL,claim_token=NULL,finished_at=#{finishedAt},updated_at=#{finishedAt}
WHERE tenant_id=#{tenantId} AND id=#{id} AND status='PROCESSING' AND claim_token=#{claimToken}
